using System;
class Program {
    static void Main() {
        uint word = 0xABCD;
        uint highByte = (word >> 8) & 0xFF;
        uint lowNibble = word & 0x0F;
        Console.WriteLine($"{highByte:X2} {lowNibble:X}");
    }
}

